#!/bin/bash
dnf update -y
dnf install -y nodejs
mkdir -p /opt/app
echo "" | base64 -d > /opt/app/app.js
echo "ewogICJuYW1lIjoJInVwbG9hZGVyLWFwcCIsCiAgInZlcnNpb24iOgkiMS4wLjAiLAogICJtYWluIjoJImFwcC5qcyIsCiAgImRlcGVuZGVuY2llcyI6IHsKICAgICJleHByZXNzIjoJIl40LjE5LjIiLAogICAgIm11bHRlciI6CSJeMS40LjUtbHRzLjEiLAogICAgIkBhd3Mtc2RrL2NsaWVudC1zMyI6ICJeMy42MDAuMCIKICB9Cn0K" | base64 -d > /opt/app/package.json
cd /opt/app
npm install --omit=dev

cat > /etc/systemd/system/uploader.service << 'SERVICE'
[Unit]
Description=Uploader App
After=network.target
[Service]
Environment=BUCKET_NAME=itmo-444-544-hvtran21-fileshare
Environment=AWS_REGION=us-east-2
Environment=PORT=3000
WorkingDirectory=/opt/app
ExecStart=/usr/bin/node /opt/app/app.js
Restart=always
User=ec2-user
[Install]
WantedBy=multi-user.target
SERVICE

chown -R ec2-user:ec2-user /opt/app
systemctl daemon-reload
systemctl enable uploader.service
systemctl start uploader.service
